// texts returns the messages without arguments in lang, nil for a
// language the catalog lacks.
func texts(lang string) *i18n.Texts {
	switch lang {
	case "en":
		return textsEn
	case "zh-Hans":
		return textsZhHans
	}
	return nil
}

// suppliedTexts are the messages without arguments other packages
// supply, by language and index.
var suppliedTexts = map[string]*[numTexts]string{}

// text says the message without arguments at i in the language of msgs,
// else of the languages it falls back to, else of the source.
func (msgs Messages) text(i int) string {
	if i18n.IsPseudo(msgs.lang) {
		return i18n.Pseudo(msgs.lang, textsEn.At(i))
	}
	for lang := msgs.lang; ; lang = i18n.Parent(lang) {
		if t := suppliedTexts[lang]; t != nil && t[i] != "" {
			return t[i]
		}
		if lang == "" {
			return textsEn.At(i)
		}
		if t := texts(lang); t != nil {
			if s := t.At(i); s != "" {
				return s
			}
		}
	}
}

// Supply adds the messages t has in lang to the catalog, over its own.
// nsgo writes the calls, in the package that supplies them, which runs
// them as it initializes.
func Supply(lang string, t Translation) {
	if len(t.Texts) > 0 {
		st := suppliedTexts[lang]
		if st == nil {
			st = new([numTexts]string)
			suppliedTexts[lang] = st
		}
		for i, key := range keyOfText {
			if s, ok := t.Texts[key]; ok {
				st[i] = s
			}
		}
	}
	s := supplied[lang]
	if t.TrayTooltip != nil {
		s.TrayTooltip = t.TrayTooltip
	}
	if t.WinOpen != nil {
		s.WinOpen = t.WinOpen
	}
	if t.WinOpenWithApp != nil {
		s.WinOpenWithApp = t.WinOpenWithApp
	}
	if t.WinRun != nil {
		s.WinRun = t.WinRun
	}
	if t.WinBrowseFolder != nil {
		s.WinBrowseFolder = t.WinBrowseFolder
	}
	if t.WinPreviewFailed != nil {
		s.WinPreviewFailed = t.WinPreviewFailed
	}
	if t.InfoLastModified != nil {
		s.InfoLastModified = t.InfoLastModified
	}
	if t.InfoSize != nil {
		s.InfoSize = t.InfoSize
	}
	if t.InfoDriveSpace != nil {
		s.InfoDriveSpace = t.InfoDriveSpace
	}
	if t.InfoFolderCounts != nil {
		s.InfoFolderCounts = t.InfoFolderCounts
	}
	if t.TextTruncated != nil {
		s.TextTruncated = t.TextTruncated
	}
	if t.TextLinesLabel != nil {
		s.TextLinesLabel = t.TextLinesLabel
	}
	if t.CsvStats != nil {
		s.CsvStats = t.CsvStats
	}
	if t.ArchSummary != nil {
		s.ArchSummary = t.ArchSummary
	}
	if t.ArchBinaryEntry != nil {
		s.ArchBinaryEntry = t.ArchBinaryEntry
	}
	if t.FontCopiedGlyph != nil {
		s.FontCopiedGlyph = t.FontCopiedGlyph
	}
	if t.HexSize != nil {
		s.HexSize = t.HexSize
	}
	if t.OfficeTruncatedRows != nil {
		s.OfficeTruncatedRows = t.OfficeTruncatedRows
	}
	if t.OfficeTruncatedCols != nil {
		s.OfficeTruncatedCols = t.OfficeTruncatedCols
	}
	if t.ModelStats != nil {
		s.ModelStats = t.ModelStats
	}
	supplied[lang] = s
	Catalog.Add(lang)
}

// arg is what an argument wrote, marked in the source's message for a
// pseudo locale.
func (msgs Messages) arg(s string) string {
	if msgs.mark {
		return i18n.Arg(s)
	}
	return s
}

